/**
 * Mock Supabase client that serves data from the static JSON file
 * generated by pipeline.py (public/data/crypto_data.json).
 *
 * Implements the chainable query builder interface that the dashboard
 * components expect:
 *   supabase.from('table').select('*').eq(f, v).order(f, {ascending}).limit(n)
 *
 * When awaited the chain resolves to { data, error }.
 */

class QueryBuilder {
  constructor(rows) {
    this._rows    = rows;
    this._filters = [];
    this._orderBy = null;
    this._asc     = true;
    this._limit   = null;
  }

  select() {
    return this;
  }

  eq(field, value) {
    this._filters.push({ field, value });
    return this;
  }

  order(field, { ascending = true } = {}) {
    this._orderBy = field;
    this._asc     = ascending;
    return this;
  }

  limit(n) {
    this._limit = n;
    return this;
  }

  // Implement the Promise protocol so `await builder` works.
  then(resolve, reject) {
    try {
      let result = [...this._rows];

      for (const { field, value } of this._filters) {
        result = result.filter((row) => row[field] === value);
      }

      if (this._orderBy) {
        const key = this._orderBy;
        const asc = this._asc;
        result.sort((a, b) => {
          const va = a[key];
          const vb = b[key];
          if (va === vb) return 0;
          return asc ? (va > vb ? 1 : -1) : (va < vb ? 1 : -1);
        });
      }

      if (this._limit !== null) {
        result = result.slice(0, this._limit);
      }

      resolve({ data: result, error: null });
    } catch (err) {
      if (reject) reject({ data: null, error: err });
    }
  }
}

class MockSupabaseClient {
  constructor(data) {
    this._data = data;
  }

  from(table) {
    return new QueryBuilder(this._data[table] || []);
  }
}

/**
 * Load the static JSON file and return a MockSupabaseClient instance.
 * Cached after the first load.
 */
let _cachedClient = null;

export async function getMockClient() {
  if (_cachedClient) return _cachedClient;

  try {
    const res  = await fetch('/data/crypto_data.json');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    _cachedClient = new MockSupabaseClient(data);
  } catch (err) {
    console.warn('crypto_data.json not found — using empty mock client.', err);
    _cachedClient = new MockSupabaseClient({});
  }

  return _cachedClient;
}
